const NoHeading = () => <ActionSheet
    open
    heading={undefined}
    actions={[
      { id: 'share', label: 'Share', icon: 'external' },
      { id: 'rename', label: 'Rename' },
      { id: 'duplicate', label: 'Duplicate' },
      { id: 'archive', label: 'Archive', disabled: true },
      { id: 'delete', label: 'Delete photo', tone: 'danger' },
    ]} />;

const Keyboard = (args) => {
  function Open(): React.JSX.Element {
    const [open, setOpen] = React.useState(true);
    return (
      <Stack gap="loose" align="start">
        <Button label="More actions" onPress={() => setOpen(true)} />
        <ActionSheet {...args} open={open} onClose={() => setOpen(false)} onAction={() => setOpen(false)} />
      </Stack>
    );
  }
  return <Open />;
};

const Dismissible = (args) => {
  const [visible, setVisible] = React.useState(true);
  return visible ? <Alert {...args} onDismiss={() => setVisible(false)} /> : <></>;
};

const Keyboard = (args) => {
  function Open(): React.JSX.Element {
    const [open, setOpen] = React.useState(true);
    return (
      <Stack gap="loose" align="start">
        <Button label="Delete files" variant="danger" onPress={() => setOpen(true)} />
        <Input label="Project name" name="name" defaultValue="Marketing site" />
        <Input label="Description" name="description" />
        <AlertDialog
          {...args}
          open={open}
          onCancel={() => setOpen(false)}
          onConfirm={() => setOpen(false)}
        />
      </Stack>
    );
  }
  return <Open />;
};

const NotDismissible = () => <BottomSheet
    open
    heading="Filters"
    footer={(<>
      <Button label="Delete account" variant="danger" />
      <Button label="Keep account" variant="secondary" />
    </>)}
    height="content"
    dismissible={false}
    dragToDismiss><Text>Narrow results by price, distance and rating.</Text></BottomSheet>;

const Keyboard = (args) => {
  function Open(): React.JSX.Element {
    const [open, setOpen] = React.useState(true);
    return (
      <Stack gap="loose" align="start">
        <Button label="Open filters" onPress={() => setOpen(true)} />
        <BottomSheet
          {...args}
          open={open}
          onClose={() => setOpen(false)}
          footer={
            <>
              <Button label="Apply" variant="primary" onPress={() => setOpen(false)} />
              <Button label="Reset" variant="secondary" onPress={() => setOpen(false)} />
            </>
          }
        >
          <Stack gap="loose">
            <Input label="Minimum price" name="min-price" />
            <Input label="Maximum price" name="max-price" />
            <Link href="#" label="Clear all filters" />
          </Stack>
        </BottomSheet>
      </Stack>
    );
  }
  return <Open />;
};

